+++ b/recreate-60573/check.js
@@ -0,0 +1,42 @@
+// Check for the "type assertion regression in TypeScript 5.7" report.
+// Exits non-zero while `type Test` (in repro.ts, the reporter's exact code) is
+// displayed as `{ prop1: Wrapper<"hello">; }`; exits 0 when it is `{ prop1: "hello"; }`.
+// Usage: node recreate-60573/check.js            (uses built/local/typescript.js)
+//        TS_PATH=/path/to/typescript.js node recreate-60573/check.js
+const path = require("path");
+const fs = require("fs");
+const ts = require(process.env.TS_PATH || path.resolve(__dirname, "../built/local/typescript.js"));
+
+const fileName = path.resolve(__dirname, "repro.ts");
+const text = fs.readFileSync(fileName, "utf8");
+const options = { strict: true, noEmit: true, target: ts.ScriptTarget.ESNext, types: [] };
+const host = {
+    getScriptFileNames: () => [fileName],
+    getScriptVersion: () => "1",
+    getScriptSnapshot: f => f === fileName ? ts.ScriptSnapshot.fromString(text) : (fs.existsSync(f) ? ts.ScriptSnapshot.fromString(fs.readFileSync(f, "utf8")) : undefined),
+    getCurrentDirectory: () => __dirname,
+    getCompilationSettings: () => options,
+    getDefaultLibFileName: o => ts.getDefaultLibFilePath(o),
+    fileExists: ts.sys.fileExists,
+    readFile: ts.sys.readFile,
+    readDirectory: ts.sys.readDirectory,
+    directoryExists: ts.sys.directoryExists,
+    getDirectories: ts.sys.getDirectories,
+};
+const service = ts.createLanguageService(host);
+
+// What the playground hover / `//    ^?` shows for `type Test`.
+const position = text.indexOf("type Test") + "type ".length;
+const info = service.getQuickInfoAtPosition(fileName, position);
+const actual = info ? ts.displayPartsToString(info.displayParts) : "<no quick info>";
+const expected = 'type Test = {\n    prop1: "hello";\n}';
+
+console.log("typescript " + ts.version);
+console.log("quick info for Test:\n" + actual);
+
+const normalize = s => s.replace(/\s+/g, " ").trim();
+if (normalize(actual) !== normalize(expected)) {
+    console.error("\nFAIL: expected " + JSON.stringify(normalize(expected)) + "\n      actual   " + JSON.stringify(normalize(actual)));
+    process.exit(1);
+}
+console.log("\nPASS");
diff --git a/recreate-60573/decl-emit-repro.ts b/recreate-60573/decl-emit-repro.ts
new file mode 100644
index 000000000..db071ca7c
--- /dev/null
+++ b/recreate-60573/decl-emit-repro.ts
@@ -0,0 +1,22 @@
+export type Wrapper<T> = {
+    _type: T
+}
+
+export function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+export function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+export const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+export type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>>
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> }
+    : T['_type']
+
+export declare function unwrap<T extends Wrapper<any>>(w: T): Unwrap<T>;
+export const result = unwrap(value);
diff --git a/recreate-60573/decl-emit.js b/recreate-60573/decl-emit.js
new file mode 100644
