--- /dev/null
+++ b/recreate-60573/decl-emit.js
@@ -0,0 +1,8 @@
+// Side evidence (not the check): declaration emit of the same code writes the wrong type into the .d.ts.
+// Usage: node recreate-60573/decl-emit.js [path/to/typescript.js]
+const path = require("path");
+const ts = require(process.argv[2] || path.resolve(__dirname, "../built/local/typescript.js"));
+const file = path.resolve(__dirname, "decl-emit-repro.ts");
+const prog = ts.createProgram([file], { strict: true, declaration: true, emitDeclarationOnly: true, target: ts.ScriptTarget.ESNext, types: [] });
+console.log("typescript " + ts.version);
+prog.emit(undefined, (name, text) => { if (name.endsWith(".d.ts")) console.log(text.split("\n").filter(l => /result|prop1/.test(l)).join("\n")); });
